"""Ordering, selection and ranking helpers."""

from __future__ import annotations

from .keys import order_records, record_key
from .records import normalize_records


def sort_records(records):
    """Return records in display order."""
    return order_records(normalize_records(records))


def top_k(records, k):
    """Return the first k records in display order."""
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an integer")
    if k <= 0:
        return []
    return sort_records(records)[:k]

"""Shared ordering rules for employee records."""

from __future__ import annotations

from .records import normalize_name, parse_age


def record_key(record):
    """Return the multi-key ordering tuple for one record."""
    age = parse_age(record["age"])
    name = normalize_name(record["name"])
    return (-age, name)


def order_records(records):
    """Return records ordered by descending age then ascending name."""
    return sorted(records, key=record_key, reverse=True)

